import { readFile, writeFile } from "node:fs/promises";
import {
  cornerProfiles,
  roundedMask,
  erode,
  polygon,
  frameSvg,
  backgroundLayers,
} from "./lib/pixel-geometry.mjs";

const lines = [
  "/* Generated by scripts/generate-pixel-geometry.mjs. Do not edit coordinates.",
  "   Circle: n = radius/grid; x = round(n - sqrt(n² - (n - row - 0.5)²)) × grid.",
  "   Insets: four-neighbour erosion in CSS pixels, not scaled outer polygons. */",
  ":root {",
];
for (const [name, profile] of Object.entries(cornerProfiles)) {
  const size = profile.radius * 2 + 8;
  const mask = roundedMask(size, size, profile);
  lines.push(
    `  /* ${name}: radius ${profile.radius}px, grid ${profile.grid}px. */`,
  );
  lines.push(`  --corner-${name}: ${polygon(mask)};`);
  for (const stroke of [0, 1, 2]) {
    lines.push(
      `  --corner-${name}-inset-${stroke}: ${polygon(erode(mask, stroke), stroke)};`,
    );
  }
  if (name === "feature" || name === "control") {
    // Joined scenery and split controls keep only their outer corners rounded,
    // using the same eroded contour as the surrounding frame.
    const inner = erode(mask, 2)
      .slice(2, -2)
      .map((row) => row.slice(2, -2));
    for (const edge of name === "feature"
      ? ["top", "left"]
      : ["left", "right"]) {
      const joined = inner.map((row, y) =>
        row.map(
          (filled, x) =>
            filled ||
            (edge === "top"
              ? y >= inner.length / 2
              : edge === "left"
                ? x >= row.length / 2
                : x < row.length / 2),
        ),
      );
      lines.push(`  --corner-${name}-${edge}-inset-2: ${polygon(joined)};`);
    }
  }
}
const circle = roundedMask(16, 16, { radius: 8, grid: 1 });
lines.push(`  --corner-circle: ${polygon(circle, 0, true)};`);
lines.push(`  --corner-circle-inset: ${polygon(erode(circle, 1), 1, true)};`);

// Each template renders at 1:1. The small slice fits a 12px range track without
// triggering the browser's proportional border-image downscaling.
const slices = Object.fromEntries(
  ["control", "menu", "badge"].map((name) => {
    const profile = cornerProfiles[name];
    const mask = roundedMask(
      profile.radius * 2 + 8,
      profile.radius * 2 + 8,
      profile,
    );
    // Preserve the entire corner plus the 2px eroded border in each fixed slice.
    return [name, mask[0].indexOf(true) + 2];
  }),
);
for (const name of ["control", "menu", "badge"]) {
  const slice = slices[name];
  const mask = roundedMask(slice * 3, slice * 3, cornerProfiles[name]);
  const layers = backgroundLayers(mask);
  lines.push(`  --pixel-frame-slice-${name}: ${slice};`);
  lines.push(`  --pixel-background-size-${name}: ${layers.join(", ")};`);
  if (name === "control") {
    const fill = backgroundLayers(erode(mask, 2));
    lines.push(
      `  --pixel-field-background-size: ${[...fill, ...layers].join(", ")};`,
    );
  }
}
lines.push("}");

const themes = [
  [":root", { line: "#8a9f8e", active: "#32785b", error: "#b23e43" }],
  [
    ':root[data-theme="dark"]',
    { line: "#526958", active: "#81c69b", error: "#f19a9e" },
  ],
  [':root[data-accent="puce"]', { line: "#a18b93", active: "#865c62" }],
  [':root[data-accent="ebony"]', { line: "#879caa", active: "#446d8a" }],
  [
    ':root[data-theme="dark"][data-accent="puce"]',
    { line: "#72545f", active: "#d8aab4" },
  ],
  [
    ':root[data-theme="dark"][data-accent="ebony"]',
    { line: "#506c80", active: "#9cbdda" },
  ],
];
for (const [selector, colors] of themes) {
  lines.push(`${selector} {`);
  for (const [state, color] of Object.entries(colors)) {
    lines.push(`  --px-frame-${state}-color: ${color};`);
    for (const [suffix, profile] of [
      ["", "control"],
      ["-menu", "menu"],
      ["-small", "badge"],
    ]) {
      const slice = slices[profile];
      const mask = roundedMask(slice * 3, slice * 3, cornerProfiles[profile]);
      lines.push(
        `  --px-frame-${state}${suffix}: url("data:image/svg+xml,${encodeURIComponent(frameSvg(mask, 2, color))}");`,
      );
    }
  }
  lines.push("}");
}
// Resolve background colors on the element using them, not on :root before
// --pixel-surface is overridden locally (custom properties inherit computed values).
for (const selector of [
  ".pixel-surface",
  "input.pixel-range-input::-webkit-slider-thumb",
  "input.pixel-range-input::-moz-range-thumb",
]) {
  lines.push(`${selector} {`);
  for (const name of ["control", "menu", "badge"]) {
    const slice = slices[name];
    const layers = backgroundLayers(
      roundedMask(slice * 3, slice * 3, cornerProfiles[name]),
    );
    lines.push(
      `  --pixel-background-${name}: ${layers.map(() => "linear-gradient(var(--pixel-surface), var(--pixel-surface))").join(", ")};`,
    );
    if (name === "control" && selector === ".pixel-surface") {
      const fill = backgroundLayers(
        erode(roundedMask(slice * 3, slice * 3, cornerProfiles[name]), 2),
      );
      const backgrounds = [
        ...fill.map(
          () => "linear-gradient(var(--pixel-surface), var(--pixel-surface))",
        ),
        ...layers.map(
          () =>
            "linear-gradient(var(--pixel-field-border), var(--pixel-field-border))",
        ),
      ];
      lines.push(`  --pixel-field-background: ${backgrounds.join(", ")};`);
    }
  }
  lines.push("}");
}

const output = `${lines.join("\n")}\n`;
const target = new URL("../src/pixel-geometry.css", import.meta.url);
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== output)
    throw new Error("Pixel geometry is stale. Run npm run generate:corners.");
  console.log("Pixel geometry matches its mathematical source.");
} else {
  await writeFile(target, output);
  console.log("Generated src/pixel-geometry.css.");
}
